#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

async function runMigrations() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory not found: ${MIGRATIONS_DIR}`);
      return;
    }

    // Read all files in migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter SQL files and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    // Log each filename that would be applied
    for (const file of sqlFiles) {
      console.log(`Would apply: ${file}`);
    }

    console.log(`\nTotal: ${sqlFiles.length} migration(s) found.`);
  } catch (error) {
    console.error('Error running migrations:', error.message);
    process.exit(1);
  }
}

runMigrations();

