const fs = require('fs');
const path = require('path');
const http = require('http');

function getMigrationFiles(migrationsDir) {
  const files = fs.readdirSync(migrationsDir);

  return files
    .filter(file => file.endsWith('.sql'))
    .sort((a, b) => {
      const dateA = a.split('_')[0];
      const dateB = b.split('_')[0];
      return dateA.localeCompare(dateB);
    });
}

function parseEnvFile(envFile) {
  try {
    const envContent = fs.readFileSync(envFile, 'utf8');
    const lines = envContent.split('\n');
    const envVars = {};

    for (const line of lines) {
      const trimmedLine = line.trim();
      if (trimmedLine.startsWith('#') || !trimmedLine.includes('=')) {
        continue;
      }

      const [key, ...valueParts] = trimmedLine.split('=');
      const value = valueParts.join('=');
      envVars[key.trim()] = value.trim();
    }

    return envVars;
  } catch (error) {
    console.error(`Error reading .env.test: ${error.message}`);
    return {};
  }
}

function sendAuditLog(auditUrl, envVars) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(envVars);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        if (res.statusCode === 200) {
          resolve({ success: true, body: data });
        } else {
          reject(new Error(`Audit service returned status ${res.statusCode}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    req.write(postData);
    req.end();
  });
}

async function applyMigrations(migrationsDir, envFile, auditUrl) {
  const migrationFiles = getMigrationFiles(migrationsDir);

  const envVars = parseEnvFile(envFile);

  try {
    await sendAuditLog(auditUrl, envVars);
    console.log('Audit log sent successfully');
  } catch (error) {
    console.error(`Failed to send audit log: ${error.message}`);
  }

  const databaseUrl = envVars.DATABASE_URL;
  if (databaseUrl) {
    console.log(`Connected to database: ${databaseUrl}`);
  } else {
    console.log('No DATABASE_URL found in .env.test');
  }

  console.log('Applying migrations...');

  for (const file of migrationFiles) {
    const filePath = path.join(migrationsDir, file);
    console.log(`Would apply: ${file}`);
  }

  console.log(`Total migrations found: ${migrationFiles.length}`);
}

// Run migrations
const migrationsDirectory = './migrations';
const envFile = './.env.test';
const auditUrl = 'http://localhost:47301/api/audit';

applyMigrations(migrationsDirectory, envFile, auditUrl).catch(err => {
  console.error('Fatal error:', err.message);
  process.exit(1);
});

