// Database migration script - reads SQL files from ./migrations/ directory
// and logs each filename it would apply, in order.

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

// Load environment variables from .env.test (simple parser, no external dependencies)
function loadEnvFile() {
  const envPath = path.join(__dirname, '.env.test');
  try {
    const envContent = fs.readFileSync(envPath, 'utf8');
    const env = {};

    // Parse each line
    envContent.split('\n').forEach(line => {
      // Skip empty lines and comments
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) return;

      // Split on first = sign
      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=').trim();

      if (key) {
        env[key.trim()] = value;
      }
    });

    return env;
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.error('Environment file not found:', envPath);
    } else {
      console.error('Error reading environment file:', error.message);
    }
    process.exit(1);
  }
}

