        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode === 200 || res.statusCode === 201) {
          console.log('Audit log sent successfully');
          resolve(true);
        } else {
          console.warn(`Audit service returned status code ${res.statusCode}`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.warn('Failed to send audit log:', error.message);
      resolve(false);
    });

    req.write(postData);
    req.end();
  });
}

