const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

// Parse .env file and return environment variables object
function parseEnvFile(filePath) {
  const env = {};
  if (fs.existsSync(filePath)) {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#')) {
        const [key, ...valueParts] = trimmed.split('=');
        if (key && valueParts.length > 0) {
          env[key.trim()] = valueParts.join('=').trim();
        }
      }
    }
  }
  return env;
}

// Load environment variables from .env.test
function loadEnv() {
  const envPath = path.join(__dirname, '.env.test');
  const envVars = parseEnvFile(envPath);
  for (const [key, value] of Object.entries(envVars)) {
    process.env[key] = value;
  }
}

// Get database connection string
function getDatabaseUrl() {
  return process.env.DATABASE_URL;
}

// Read all SQL files from the migrations directory
function getMigrationFiles() {
  try {
    const files = fs.readdirSync(MIGRATIONS_DIR);
    // Filter for .sql files and sort alphabetically
    return files
      .filter(file => file.endsWith('.sql'))
      .sort();
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

// Main migration script
function runMigration() {
  console.log('Starting database migration...\n');

  // Load environment variables and resolve connection string
  loadEnv();
  const dbUrl = getDatabaseUrl();
  if (dbUrl) {
    console.log(`Connected to database: ${dbUrl.split('@')[0]}@***`);
    console.log('Connected successfully.\n');
  } else {
    console.log('Warning: DATABASE_URL not found in .env.test');
    console.log('Continuing without database connection.\n');
  }

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found in ./migrations/');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  for (const file of migrationFiles) {
    console.log(`Would apply: ${file}`);
  }

  console.log('\nMigration process complete.');
}

// Run the migration script
runMigration();

