      .sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in', MIGRATIONS_DIR);
      return;
    }

    console.log('Applying migrations:');
    sqlFiles.forEach(file => {
      console.log(file);
    });

  } catch (error) {
    console.error('Error running migrations:', error.message);
    process.exit(1);
  }
}

